Object.assign(STRINGS.en,{google_connected:'Google connected',google_email:'Google account',google_last_sync:'Last sync',tax_notice:'Configure this according to the shop’s registration and current rules; this is not tax advice.',google_error:'Sync error',sync_now:'Sync now',import_products:'Allow product and stock edits from Sheets',import_expenses:'Allow expense edits from Sheets',google_secret_hint:'Configured; leave blank to keep the current secret',oauth_host_hint:'Open this POS on the host computer to authorize Google. First sync creates a spreadsheet.',refund_order:'Record refund',refund_warning:'Complete the refund through the payment provider first, then record it here.',refund_done:'Refund recorded'});
