const NAV=[['pos','nav_pos','▣'],['orders','nav_orders','▤'],['products','nav_products','⬡'],['stock','nav_stock','⌂'],['ledger','nav_ledger','▱'],['reports','nav_reports','▥'],['settings','nav_settings','⚙']];
const state={user:null,lang:localStorage.getItem('kedai-lang')||'zh',page:'pos',products:[],orders:[],expenses:[],users:[],settings:{},summary:{},cart:[],category:'All',search:'',orderFilter:'all',modal:null,editing:null};
const t=k=>STRINGS[state.lang]?.[k]||STRINGS.en[k]||k;
const money=c=>new Intl.NumberFormat(state.lang==='ms'?'ms-MY':'en-MY',{style:'currency',currency:'MYR'}).format((Number(c)||0)/100);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.getElementById('app');
let refreshTimer=null;
async function api(path,opts={}){const res=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const data=await res.json().catch(()=>({error:t('error')}));if(!res.ok)throw new Error(data.error||t('error'));return data}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.className='toast show';setTimeout(()=>el.className='toast',2500)}
function langSelect(id='language-select'){return `<select id="${id}" class="select-plain" aria-label="${t('language')}"><option value="zh" ${state.lang==='zh'?'selected':''}>简体中文</option><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ms" ${state.lang==='ms'?'selected':''}>Bahasa Melayu</option></select>`}
function setLang(l){state.lang=l;localStorage.setItem('kedai-lang',l);render()}
async function boot(){try{const s=await api('/api/status');if(s.setup_required){renderAuth('setup');return}state.user=s.user;if(!state.user){renderAuth('login');return}await refresh();if(!localStorage.getItem('kedai-lang')&&state.settings.language){state.lang=state.settings.language;localStorage.setItem('kedai-lang',state.lang)}render();if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(()=>refresh().then(()=>{if(state.user&&state.page==='orders')render()}),4000)}catch(e){renderUnavailable(e.message)}}
async function refresh(){if(!state.user)return;const isOwner=state.user.role==='owner';const [products,orders,expenses,summary,settings]=await Promise.all([api('/api/products'),api('/api/orders'),isOwner?api('/api/expenses'):Promise.resolve([]),api('/api/summary'),api('/api/settings')]);state.products=products;state.orders=orders;state.expenses=expenses;state.summary=summary;state.settings=settings;if(state.user.role==='owner'&&state.page==='settings')state.users=await api('/api/users');const badge=document.querySelector('[data-nav-pending]');if(badge)badge.textContent=String(orders.filter(o=>o.status==='open').length)}
function renderUnavailable(msg){app.innerHTML=`<div class="login-wrap"><div class="login-card"><div class="brand"><span class="brand-mark">店</span>${t('brand')}</div><h1>${t('connection_problem')}</h1><p>${esc(msg||'')}</p><div class="login-note">${t('network_note')}</div><button class="btn primary wide" style="margin-top:18px" onclick="boot()">${t('sign_in')}</button></div></div>`}
function renderAuth(mode){const setup=mode==='setup';app.innerHTML=`<main class="login-wrap"><form id="auth-form" class="login-card"><div class="brand"><span class="brand-mark">店</span>${t('brand')}</div><div class="inline" style="justify-content:flex-end">${langSelect('auth-lang')}</div><h1>${setup?t('setup_title'):t('login_title')}</h1><p>${setup?t('setup_subtitle'):t('login_subtitle')}</p>${setup?`<div class="field"><label>${t('display_name')}</label><input name="display_name" value="Owner" required></div>`:''}<div class="field"><label>${t('username_label')}</label><input name="username" autocomplete="username" required minlength="3" value="${setup?'owner':''}"></div><div class="field"><label>${t('password_label')}</label><input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" required minlength="${setup?8:1}"></div>${setup?`<div class="login-note">${t('setup_note')}</div>`:''}<button class="btn primary wide" style="margin-top:17px">${setup?t('create_owner'):t('sign_in')}</button></form></main>`;
 document.getElementById('auth-lang').onchange=e=>{state.lang=e.target.value;localStorage.setItem('kedai-lang',state.lang);renderAuth(mode)};
 document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api(setup?'/api/setup':'/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.user=r.user;await refresh();render();if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(()=>refresh().then(()=>{if(state.page==='orders')render()}),4000)}catch(err){toast(err.message)}}}
function render(){if(!state.user){renderAuth('login');return}const shop=state.settings.shop_name||'Kedai POS';app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">店</span>${esc(shop)}</div><nav class="nav">${(state.user.role==='owner'?NAV:NAV.filter(x=>['pos','orders'].includes(x[0]))).map(([id,key,ic])=>`<button class="nav-btn ${state.page===id?'active':''}" data-page="${id}"><span class="icon">${ic}</span><span>${t(key)}</span>${id==='orders'?`<small data-nav-pending style="margin-left:auto">${state.orders.filter(o=>o.status==='open').length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="user-card"><div class="avatar">${esc((state.user.display_name||'?').slice(0,1))}</div><div><strong>${esc(state.user.display_name)}</strong><small>${t(state.user.role)}</small></div><button class="icon-btn" id="logout-btn" title="${t('logout')}">↪</button></div></div></aside><main class="main"><header class="topbar"><div class="global-search">⌕ <input id="global-search" placeholder="${t('search')}" value="${esc(state.search)}"></div><div class="top-meta">${langSelect()}<span class="status"><i class="dot"></i><span class="status-label">${t('online')}</span></span><span class="status"><span>☁</span><span class="host-label">${t('host_synced')}</span></span><button class="avatar" id="logout-mobile" title="${t('logout')}">${esc((state.user.display_name||'?').slice(0,1))}</button></div></header><section id="page-content" class="page">${renderPage()}</section></main></div>${state.modal?renderModal():''}`;
 document.getElementById('language-select').onchange=e=>setLang(e.target.value);
 document.getElementById('global-search').oninput=e=>{const caret=e.target.selectionStart;state.search=e.target.value;if(state.page==='pos'||state.page==='orders'){render();const input=document.getElementById('global-search');input.focus();input.setSelectionRange(caret,caret)}};document.getElementById('global-search').onkeydown=e=>{if(e.key==='Enter'&&state.page==='pos'){const p=state.products.find(x=>x.sku&&x.sku.toLowerCase()===state.search.trim().toLowerCase());if(p){const found=state.cart.find(x=>x.product.id===p.id);if(found)found.quantity++;else state.cart.push({product:p,quantity:1});state.search='';render()}}};
 document.getElementById('logout-btn')?.addEventListener('click',logout);
 document.getElementById('logout-mobile')?.addEventListener('click',logout);
 bindPage();
}
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'})}catch{}state.user=null;state.cart=[];state.page='pos';renderAuth('login')}
function renderPage(){switch(state.page){case'pos':return renderPOS();case'orders':return renderOrders();case'products':return renderProducts();case'stock':return renderStock();case'ledger':return renderLedger();case'reports':return renderReports();case'settings':return renderSettings();default:return renderPOS()}}
function categories(){return ['All',...new Set(state.products.map(p=>p.category||'General'))]}
function displayCategory(c){if(c==='All')return t('all');if(c==='Drinks')return t('category_drinks');if(c==='Food')return t('category_food');if(c==='Daily goods')return t('category_daily');if(c==='General')return t('category_general');return c}
function renderPOS(){const products=state.products.filter(p=>(state.category==='All'||p.category===state.category)&&(!state.search||`${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(state.search.toLowerCase())));const subtotal=state.cart.reduce((s,x)=>s+x.product.price_cents*x.quantity,0);const taxOn=state.settings.tax_enabled===true;const rate=Number(state.settings.tax_rate||0);const tax=taxOn?Math.round(subtotal*rate/100):0;return `<div class="page-head"><div><h1>${t('title_pos')}</h1><p>${t('subtitle_pos')}</p></div>${state.user.role==='owner'?`<button class="btn" data-action="add-product">＋ ${t('add_product')}</button>`:''}</div><div class="pos-layout"><section class="catalog-panel"><div class="catalog-toolbar"><div class="categories">${categories().map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${esc(c)}">${esc(displayCategory(c))}</button>`).join('')}</div><span class="muted">${products.length} ${t('products')}</span></div>${products.length?`<div class="product-grid">${products.map(p=>`<article class="product-card" data-add="${p.id}"><div class="product-photo">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:`<span>▧</span>`}</div><div class="product-info"><div style="min-width:0"><div class="product-name">${esc(p.name)}</div><div class="product-category">${esc(displayCategory(p.category))}</div><div class="product-price">${money(p.price_cents)}</div>${p.stock<=5?`<div class="stock-low">${t('low_stock')}: ${p.stock}</div>`:''}</div><button class="add-product" aria-label="${t('add_product')}">+</button></div></article>`).join('')}</div>`:`<div class="card empty"><div class="empty-icon">▧</div><div>${state.products.length?t('no_products'):t('no_products')}</div>${!state.products.length?`<button class="btn soft" data-action="add-product" style="margin-top:14px">${t('add_first_product')}</button>`:''}</div>`}</section><aside class="cart-panel"><div class="cart-head"><h2>${t('cart')} (${state.cart.reduce((s,x)=>s+x.quantity,0)})</h2><button class="icon-btn" data-action="clear-cart">⌫ ${t('clear')}</button></div>${state.cart.length?`<div class="cart-list">${state.cart.map((x,i)=>`<div class="cart-row"><img class="cart-thumb" src="${x.product.image||''}" onerror="this.style.display='none'" alt=""><div><div class="cart-item-name">${esc(x.product.name)}</div><div class="cart-item-price">${money(x.product.price_cents)} × ${x.quantity}</div></div><div class="quantity"><button data-qty="${i}" data-delta="-1">−</button><b>${x.quantity}</b><button data-qty="${i}" data-delta="1">+</button></div></div>`).join('')}</div><div class="cart-summary"><div class="sum-row"><span>${t('subtotal')}</span><span>${money(subtotal)}</span></div>${taxOn?`<div class="sum-row"><span>${esc(state.settings.tax_label||t('tax'))} (${rate}%)</span><span>${money(tax)}</span></div>`:''}<div class="sum-row total"><span>${t('total')}</span><span>${money(subtotal+tax)}</span></div><div class="pay-buttons"><button class="btn soft" data-action="checkout-cash">▣ ${t('cash')}</button><button class="btn primary" data-action="checkout-qr">▦ ${t('duitnow')}</button></div><button class="btn wide" style="margin-top:9px" data-action="save-order">${t('save_order')}</button></div>`:`<div class="empty" style="margin:auto"><div class="empty-icon">🛒</div><div>${t('empty_cart')}</div><small>${t('add_products_hint')}</small></div>`}</aside></div>`}
function renderOrders(){const list=state.orders.filter(o=>state.orderFilter==='all'||o.status===state.orderFilter).filter(o=>!state.search||String(o.id).includes(state.search)||String(o.receipt_no||'').toLowerCase().includes(state.search.toLowerCase())||o.items.some(x=>x.product_name.toLowerCase().includes(state.search.toLowerCase())));return `<div class="page-head"><div><h1>${t('orders')}</h1><p>${t('open_orders')}: ${state.summary.open_orders||0}</p></div><div class="inline" style="flex:0 0 auto"><button class="btn primary" data-page="pos">＋ ${t('title_pos')}</button></div></div><div class="filters"><select id="order-filter" class="btn"><option value="all">${t('all')}</option><option value="open" ${state.orderFilter==='open'?'selected':''}>${t('open')}</option><option value="paid" ${state.orderFilter==='paid'?'selected':''}>${t('paid')}</option><option value="void" ${state.orderFilter==='void'?'selected':''}>${t('void')}</option></select><span class="muted">${list.length} ${t('orders')}</span></div><div class="order-cards">${list.length?list.map(o=>`<article class="order-card"><div><div class="inline"><span class="order-title">#${o.receipt_no||String(o.id).padStart(5,'0')}</span><span class="badge ${o.status}">${t(o.status)}</span></div><div class="order-meta">${t('created_at')}: ${dateFmt(o.created_at)} · ${t('order_by')}: ${esc(o.created_by_name||'')}</div><div class="order-lines">${o.items.map(i=>`${esc(i.product_name)} × ${i.quantity}`).join(' · ')}</div>${o.status==='paid'?`<div class="order-meta">${t('paid_at')}: ${dateFmt(o.paid_at)} · ${t('cashier')}: ${esc(o.cashier_name||'')} · ${t('payment')}: ${t(o.payment_method==='cash'?'method_cash':'method_qr')}</div>`:''}</div><div class="order-actions"><strong>${money(o.total_cents)}</strong>${o.status==='open'?`<button class="btn primary small" data-action="pay-existing" data-id="${o.id}">${t('pay_now')}</button>${state.user.role==='owner'?`<button class="btn danger small" data-action="void-order" data-id="${o.id}">${t('void_order')}</button>`:''}`:`<button class="btn small" data-action="receipt" data-id="${o.id}">${t('view_receipt')}</button>${o.status==='paid'&&state.user.role==='owner'?`<button class="btn danger small" data-action="refund-order" data-id="${o.id}">${t('refund_order')}</button>`:''}`}</div></article>`).join(''):`<div class="card empty"><div class="empty-icon">▤</div>${t('no_orders')}</div>`}</div>`}
function renderProducts(){return `<div class="page-head"><div><h1>${t('products')}</h1><p>${state.products.length} ${t('products')}</p></div><button class="btn primary" data-action="add-product">＋ ${t('add_product')}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('product_name')}</th><th>${t('category')}</th><th>${t('sku')}</th><th>${t('price')}</th><th>${t('stock')}</th><th>${t('actions')}</th></tr></thead><tbody>${state.products.length?state.products.map(p=>`<tr><td><div class="inline"><img src="${esc(p.image||'')}" onerror="this.style.display='none'" style="width:38px;height:38px;object-fit:cover;border-radius:8px"><strong>${esc(p.name)}</strong></div></td><td>${esc(displayCategory(p.category))}</td><td>${esc(p.sku||'—')}</td><td>${money(p.price_cents)}</td><td>${p.stock}</td><td><button class="btn small" data-action="edit-product" data-id="${p.id}">${t('edit_product')}</button></td></tr>`).join(''):`<tr><td colspan="6" class="center muted">${t('no_products')}</td></tr>`}</tbody></table></div>`}
function renderStock(){const sorted=[...state.products].sort((a,b)=>a.stock-b.stock);return `<div class="page-head"><div><h1>${t('nav_stock')}</h1><p>${t('stock_value')}</p></div><button class="btn" data-page="products">${t('products')}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('product_name')}</th><th>${t('sku')}</th><th>${t('stock')}</th><th>${t('price')}</th><th>${t('actions')}</th></tr></thead><tbody>${sorted.map(p=>`<tr><td>${esc(p.name)} ${p.stock<=5?`<span class="badge open">${t('low_stock')}</span>`:''}</td><td>${esc(p.sku||'—')}</td><td><strong>${p.stock}</strong></td><td>${money(p.price_cents)}</td><td><button class="btn small" data-action="edit-product" data-id="${p.id}">${t('edit_product')}</button></td></tr>`).join('')}</tbody></table></div>`}
function renderLedger(){return `<div class="page-head"><div><h1>${t('nav_ledger')}</h1><p>${t('expense_ledger')}</p></div><button class="btn primary" data-action="add-expense">＋ ${t('add_expense')}</button></div><div class="metrics"><div class="card"><div class="metric-label">${t('today_sales')}</div><div class="metric-value">${money(state.summary.sales_cents)}</div></div><div class="card"><div class="metric-label">${t('today_orders')}</div><div class="metric-value">${state.summary.orders||0}</div></div><div class="card"><div class="metric-label">${t('today_expenses')}</div><div class="metric-value">${money(state.summary.expenses_cents)}</div></div><div class="card"><div class="metric-label">${t('net_today')}</div><div class="metric-value">${money(state.summary.net_cents)}</div></div></div><div class="card"><h2 style="margin:0 0 14px">${t('recent_expenses')}</h2>${state.expenses.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('date')}</th><th>${t('expense_name')}</th><th>${t('expense_category')}</th><th>${t('order_by')}</th><th>${t('amount')}</th></tr></thead><tbody>${state.expenses.map(x=>`<tr><td>${dateFmt(x.created_at)}</td><td>${esc(x.description)}</td><td>${esc(x.category)}</td><td>${esc(x.paid_by_name||'')}</td><td>${money(x.amount_cents)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('no_expenses')}</div>`}</div>`}
function renderReports(){const s=state.summary;return `<div class="page-head"><div><h1>${t('nav_reports')}</h1><p>${s.date||''}</p></div><button class="btn" data-action="backup">⇩ ${t('save_backup')}</button></div><div class="metrics"><div class="card"><div class="metric-label">${t('today_sales')}</div><div class="metric-value">${money(s.sales_cents)}</div><div class="metric-foot">${s.orders||0} ${t('today_orders')}</div></div><div class="card"><div class="metric-label">${t('today_expenses')}</div><div class="metric-value">${money(s.expenses_cents)}</div></div><div class="card"><div class="metric-label">${t('net_today')}</div><div class="metric-value">${money(s.net_cents)}</div></div><div class="card"><div class="metric-label">${t('open_orders')}</div><div class="metric-value">${s.open_orders||0}</div></div></div><div class="card"><h2>${t('by_payment')}</h2>${(s.by_method||[]).length?(s.by_method||[]).map(x=>`<div class="switch-row"><span>${t(x.payment_method==='cash'?'method_cash':'method_qr')} · ${x.n}</span><strong>${money(x.total)}</strong></div>`).join(''):`<p class="muted">${t('no_orders')}</p>`}</div>`}
function renderSettings(){const s=state.settings;return `<div class="page-head"><div><h1>${t('settings')}</h1><p>${t('owner_only')}</p></div><button class="btn" data-action="backup">⇩ ${t('save_backup')}</button></div><div class="settings-grid"><form id="shop-settings" class="card"><h2>${t('shop_settings')}</h2><div class="field"><label>${t('shop_name')}</label><input name="shop_name" value="${esc(s.shop_name||'Kedai POS')}"></div><div class="field"><label>${t('shop_address')}</label><input name="shop_address" value="${esc(s.shop_address||'')}"></div><div class="field"><label>${t('shop_phone')}</label><input name="shop_phone" value="${esc(s.shop_phone||'')}"></div><div class="field"><label>${t('language')}</label><select name="language"><option value="zh" ${state.lang==='zh'?'selected':''}>简体中文</option><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ms" ${state.lang==='ms'?'selected':''}>Bahasa Melayu</option></select></div><div class="field"><label>${t('timezone')}</label><input name="timezone" value="${esc(s.timezone||'Asia/Kuala_Lumpur')}"></div><button class="btn primary">${t('save_settings')}</button></form><section class="card"><h2>${t('qr_settings')}</h2><p class="muted">${t('qr_hint')}</p>${s.merchant_qr?`<img class="qr-preview" src="${esc(s.merchant_qr)}" alt="DuitNow QR">`:''}<form id="qr-form"><div class="field"><label>${t('upload_image')}</label><input type="file" name="image" accept="image/png,image/jpeg,image/webp"></div><button class="btn primary">${t('save_settings')}</button></form></section><section class="card"><h2>${t('tax_settings')}</h2><form id="tax-form"><label class="switch-row"><span>${t('tax_enabled')}</span><input type="checkbox" name="tax_enabled" ${s.tax_enabled?'checked':''}></label><div class="field" style="margin-top:12px"><label>${t('tax_label')}</label><input name="tax_label" value="${esc(s.tax_label||'SST')}"></div><div class="field"><label>${t('tax_rate')}</label><input name="tax_rate" type="number" min="0" step="0.01" value="${esc(s.tax_rate||0)}"></div><p class="muted">${t('tax_notice')}</p><button class="btn primary">${t('save_settings')}</button></form></section><section class="card"><h2>${t('sync_settings')}</h2><p class="muted">${t('sync_hint')}</p><div class="field"><label>OAuth Client ID</label><input id="google-client-id" value="${esc(s.google_client_id||'')}"></div><div class="field"><label>OAuth Client Secret</label><input id="google-client-secret" type="password" placeholder="${s.google_secret_configured?t('google_secret_hint'):''}"></div><label class="switch-row"><span>${t('sync_enabled')}</span><input id="google-enabled" type="checkbox" ${s.sheet_sync_enabled?'checked':''}></label><label class="switch-row"><span>${t('import_products')}</span><input id="sheets-import-products" type="checkbox" ${s.sheets_import_products?'checked':''}></label><label class="switch-row"><span>${t('import_expenses')}</span><input id="sheets-import-expenses" type="checkbox" ${s.sheets_import_expenses?'checked':''}></label><div class="login-note" style="margin:12px 0">${t('sheets_owner')} ${t('oauth_host_hint')}<br>${s.google_email?`${t('google_email')}: ${esc(s.google_email)}`:t('google_unconfigured')}${s.google_sync_at?`<br>${t('google_last_sync')}: ${dateFmt(s.google_sync_at)}`:''}${s.google_sync_error?`<br><strong>${t('google_error')}:</strong> ${esc(s.google_sync_error)}`:''}${s.google_sheet_url?`<br><a href="${esc(s.google_sheet_url)}" target="_blank" rel="noopener">Google Sheet</a>`:''}</div><button class="btn" data-action="save-google">${t('save_settings')}</button><button class="btn soft" data-action="google-connect" style="margin-left:7px">${t('connect_google')}</button><button class="btn" data-action="google-sync" style="margin-left:7px">${t('sync_now')}</button></section><section class="card"><h2>${t('staff_accounts')}</h2><button class="btn primary" data-action="add-staff">＋ ${t('add_staff')}</button><div style="margin-top:12px">${state.users.map(u=>`<div class="switch-row"><span><strong>${esc(u.display_name)}</strong><small class="muted"> · ${esc(u.username)} · ${t(u.role)}</small></span>${u.role==='staff'?`<button class="btn small ${u.active?'':'soft'}" data-action="toggle-user" data-id="${u.id}" data-active="${u.active?0:1}">${u.active?t('disable'):t('active')}</button>`:''}</div>`).join('')}</div></section><section class="card"><h2>${t('backup')}</h2><p class="muted">${t('setup_note')}</p><button class="btn" data-action="backup">⇩ ${t('save_backup')}</button><p class="login-note" style="margin-top:12px">${t('network_note')}</p></section></div>`}
function bindPage(){document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const p=state.products.find(x=>x.id===Number(b.dataset.add));if(p){const found=state.cart.find(x=>x.product.id===p.id);if(found)found.quantity+=1;else state.cart.push({product:p,quantity:1});render()}});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.qty),d=Number(b.dataset.delta);if(state.cart[i]){state.cart[i].quantity+=d;if(state.cart[i].quantity<=0)state.cart.splice(i,1);render()}});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;refresh().then(render)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b.dataset));document.getElementById('order-filter')?.addEventListener('change',e=>{state.orderFilter=e.target.value;render()});document.getElementById('shop-settings')?.addEventListener('submit',saveShopSettings);document.getElementById('tax-form')?.addEventListener('submit',saveTax);document.getElementById('qr-form')?.addEventListener('submit',saveQr);document.getElementById('modal-form')?.addEventListener('submit',submitModal);document.getElementById('cash-received')?.addEventListener('input',updateChange);document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',e=>{if(b.classList.contains('modal-backdrop')&&e.target!==b)return;state.modal=null;render()}));document.getElementById('modal-file')?.addEventListener('change',previewImage)}
async function handleAction(action,data={}){try{switch(action){case'clear-cart':state.cart=[];render();break;case'add-product':if(state.user.role!=='owner')return toast(t('owner_only'));state.modal={type:'product'};render();break;case'edit-product':if(state.user.role!=='owner')return toast(t('owner_only'));state.modal={type:'product',product:state.products.find(p=>p.id===Number(data.id))};render();break;case'save-order':await createOrder('save');break;case'checkout-cash':await createOrder('cash');break;case'checkout-qr':await createOrder('qr');break;case'pay-existing':state.modal={type:'pay-choice',order:state.orders.find(o=>o.id===Number(data.id))};render();break;case'confirm-pay':await settleOrder(state.modal.order.id,state.modal.method);break;case'choose-cash':state.modal={type:'payment',order:state.modal.order,method:'cash'};render();break;case'choose-qr':state.modal={type:'payment',order:state.modal.order,method:'qr'};render();break;case'void-order':if(confirm(t('confirm_void'))){await api(`/api/orders/${data.id}`,{method:'DELETE'});await refresh();render()}break;case'refund-order':if(confirm(t('refund_warning'))){await api(`/api/orders/${data.id}/refund`,{method:'POST',body:JSON.stringify({note:'Full refund recorded by owner'})});await refresh();render();toast(t('refund_done'))}break;case'receipt':showReceipt(Number(data.id));break;case'add-expense':state.modal={type:'expense'};render();break;case'add-staff':state.modal={type:'staff'};render();break;case'toggle-user':await api(`/api/users/${data.id}`,{method:'PUT',body:JSON.stringify({active:data.active==='1'})});state.users=await api('/api/users');render();break;case'backup':await downloadBackup();break;case'save-google':await saveGoogle();break;case'google-connect':if(!document.getElementById('google-client-id').value.trim())return toast('Enter the Google OAuth Client ID first');await saveGoogle();window.location.href='/api/google/connect';break;case'google-sync':{const r=await api('/api/google/sync',{method:'POST',body:'{}'});await refresh();render();toast(`${t('paid_success')}: ${r.orders}`);break;}case'print':window.print();break;}}
catch(e){toast(e.message||t('error'))}}
async function createOrder(mode){if(!state.cart.length)return toast(t('empty_cart'));const result=await api('/api/orders',{method:'POST',body:JSON.stringify({items:state.cart.map(x=>({product_id:x.product.id,quantity:x.quantity}))})});state.cart=[];await refresh();if(mode==='save'){toast(t('save_order_success'));render();return}const order=state.orders.find(o=>o.id===result.id)||{id:result.id,total_cents:0,items:[]};state.modal={type:'payment',order,method:mode};render()}
function renderModal(){const m=state.modal;if(!m)return'';if(m.type==='product'){const p=m.product||{};return `<div class="modal-backdrop" data-close-modal><form id="modal-form" class="modal" data-form="product"><button type="button" class="modal-close" data-close-modal>×</button><h2>${p.id?t('edit_product'):t('add_product')}</h2><input type="hidden" name="id" value="${p.id||''}"><div class="field"><label>${t('product_name')}</label><input name="name" required value="${esc(p.name||'')}"></div><div class="form-grid"><div class="field"><label>${t('category')}</label><input name="category" list="category-list" value="${esc(p.category||'General')}"><datalist id="category-list">${categories().filter(c=>c!=='All').map(c=>`<option value="${esc(c)}">`).join('')}</datalist></div><div class="field"><label>${t('sku')}</label><input name="sku" value="${esc(p.sku||'')}"></div><div class="field"><label>${t('price')}</label><input name="price" type="number" min="0" step="0.01" required value="${p.price_cents!=null?(p.price_cents/100):''}"></div><div class="field"><label>${t('stock')}</label><input name="stock" type="number" min="0" step="0.001" value="${p.stock??0}"></div></div><div class="field"><label>${t('image')}</label><input id="modal-file" name="image_file" type="file" accept="image/*"><input type="hidden" name="image" value="${esc(p.image||'')}"><img id="image-preview" src="${esc(p.image||'')}" style="${p.image?'':'display:none;'}max-width:100px;max-height:100px;border-radius:8px"></div><div class="inline"><button type="button" class="btn" data-close-modal>${t('cancel')}</button><button class="btn primary">${t('save')}</button></div></form></div>`}
 if(m.type==='expense')return `<div class="modal-backdrop" data-close-modal><form id="modal-form" class="modal" data-form="expense"><button type="button" class="modal-close" data-close-modal>×</button><h2>${t('add_expense')}</h2><div class="field"><label>${t('expense_name')}</label><input name="description" required></div><div class="field"><label>${t('expense_category')}</label><input name="category" list="expense-categories" value="${t('exp_category_other')}"><datalist id="expense-categories"><option value="${t('exp_category_rent')}"><option value="${t('exp_category_supplies')}"><option value="${t('exp_category_utilities')}"><option value="${t('exp_category_other')}"></datalist></div><div class="field"><label>${t('expense_amount')}</label><input name="amount" type="number" min="0.01" step="0.01" required></div><div class="inline"><button type="button" class="btn" data-close-modal>${t('cancel')}</button><button class="btn primary">${t('save')}</button></div></form></div>`;
 if(m.type==='staff')return `<div class="modal-backdrop" data-close-modal><form id="modal-form" class="modal" data-form="staff"><button type="button" class="modal-close" data-close-modal>×</button><h2>${t('add_staff')}</h2><div class="field"><label>${t('staff_name')}</label><input name="display_name" required></div><div class="field"><label>${t('username')}</label><input name="username" minlength="3" required></div><div class="field"><label>${t('password')}</label><input name="password" type="password" minlength="8" required></div><div class="inline"><button type="button" class="btn" data-close-modal>${t('cancel')}</button><button class="btn primary">${t('add_staff')}</button></div></form></div>`;
 if(m.type==='pay-choice')return `<div class="modal-backdrop" data-close-modal><section class="modal"><button class="modal-close" data-close-modal>×</button><h2>${t('choose_payment')}</h2><div class="modal-total">${money(m.order.total_cents)}</div><div class="pay-buttons" style="margin-top:24px"><button class="btn soft" data-action="choose-cash">▣ ${t('cash')}</button><button class="btn primary" data-action="choose-qr">▦ ${t('duitnow')}</button></div></section></div>`;
 if(m.type==='payment'){const qr=state.settings.merchant_qr;return `<div class="modal-backdrop" data-close-modal><section class="modal"><button class="modal-close" data-close-modal>×</button><h2>${m.method==='qr'?t('payment_qr_title'):t('cash_title')}</h2><div class="modal-total">${money(m.order.total_cents)}</div>${m.method==='qr'?`${qr?`<img class="qr-display" src="${esc(qr)}" alt="DuitNow QR">`:`<div class="login-note center" style="margin:18px 0">${t('no_qr')}</div>`}<p class="center muted">${t('scan_to_pay')}</p><button class="btn primary wide" data-action="confirm-pay">${t('confirm_paid')}</button>`:`<div class="field" style="margin-top:18px"><label>${t('cash_received')}</label><input id="cash-received" type="number" min="${(m.order.total_cents/100).toFixed(2)}" step="0.01" value="${(m.order.total_cents/100).toFixed(2)}"></div><div class="sum-row total"><span>${t('change_due')}</span><span id="change-value">${money(0)}</span></div><button class="btn primary wide" data-action="confirm-pay">${t('confirm_cash')}</button>`}</section></div>`}
 if(m.type==='receipt'){const o=m.order;return `<div class="modal-backdrop" data-close-modal><section class="modal"><button class="modal-close" data-close-modal>×</button><div id="receipt-content"><div class="center"><h2>${esc(state.settings.shop_name||t('brand'))}</h2><p>${esc(state.settings.shop_address||'')}<br>${esc(state.settings.shop_phone||'')}</p><h3>${t('receipt')}</h3><p>${t('receipt_no')}: ${esc(o.receipt_no||'')}</p><p>${dateFmt(o.paid_at||o.created_at)}</p></div><hr>${o.items.map(i=>`<div class="sum-row"><span>${esc(i.product_name)} × ${i.quantity}</span><strong>${money(i.line_total_cents)}</strong></div>`).join('')}<hr><div class="sum-row"><span>${t('subtotal')}</span><span>${money(o.subtotal_cents)}</span></div>${o.tax_cents?`<div class="sum-row"><span>${esc(state.settings.tax_label||t('tax'))}</span><span>${money(o.tax_cents)}</span></div>`:''}<div class="sum-row total"><span>${t('total')}</span><span>${money(o.total_cents)}</span></div><p>${t('payment')}: ${t(o.payment_method==='cash'?'method_cash':'method_qr')}</p>${o.payment_method==='cash'?`<p>${t('cash_received')}: ${money(o.cash_received_cents)} · ${t('change_due')}: ${money(o.change_cents)}</p>`:''}<p class="center">${t('thank_you')}</p></div><button class="btn primary wide" data-action="print">${t('print')}</button></section></div>`}
 return''}
async function previewImage(e){const f=e.target.files?.[0];if(!f)return;try{const data=await compressImage(f);document.querySelector('[name="image"]')?.setAttribute('value',data);document.querySelector('[name="image"]').value=data;const img=document.getElementById('image-preview');if(img){img.src=data;img.style.display='block'}}catch(err){toast(err.message)}}
function readImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read image'));reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)})}
function compressImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read image'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Invalid image'));img.onload=()=>{const scale=Math.min(1,1000/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};img.src=reader.result};reader.readAsDataURL(file)})}
async function submitModal(e){e.preventDefault();const form=e.currentTarget;const kind=form.dataset.form;const f=new FormData(form);try{if(kind==='product'){const p=Object.fromEntries(f);delete p.image_file;const file=form.querySelector('[name="image_file"]').files[0];if(file)p.image=await compressImage(file);if(p.id){const id=p.id;delete p.id;await api(`/api/products/${id}`,{method:'PUT',body:JSON.stringify(p)})}else await api('/api/products',{method:'POST',body:JSON.stringify(p)});state.modal=null;await refresh();render();toast(t('product_saved'))}else if(kind==='expense'){await api('/api/expenses',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.modal=null;await refresh();render();toast(t('expense_saved'))}else if(kind==='staff'){await api('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.modal=null;state.users=await api('/api/users');render();toast(t('staff_saved'))}}catch(err){toast(err.message)}}
async function saveShopSettings(e){e.preventDefault();const vals=Object.fromEntries(new FormData(e.currentTarget));await api('/api/settings',{method:'POST',body:JSON.stringify(vals)});state.lang=vals.language||state.lang;localStorage.setItem('kedai-lang',state.lang);await refresh();render();toast(t('settings_saved'))}
async function saveTax(e){e.preventDefault();const fd=new FormData(e.currentTarget);await api('/api/settings',{method:'POST',body:JSON.stringify({tax_enabled:fd.has('tax_enabled'),tax_label:fd.get('tax_label'),tax_rate:Number(fd.get('tax_rate')||0)})});await refresh();render();toast(t('settings_saved'))}
async function saveQr(e){e.preventDefault();const f=e.currentTarget.querySelector('input[type=file]').files[0];if(!f)return toast(t('required'));const qr=await readImage(f);if(qr.length>5*1024*1024)return toast('QR image must be smaller than 4 MB');await api('/api/settings',{method:'POST',body:JSON.stringify({merchant_qr:qr})});await refresh();render();toast(t('settings_saved'))}
async function saveGoogle(){const payload={google_client_id:document.getElementById('google-client-id').value,sheet_sync_enabled:document.getElementById('google-enabled').checked,sheets_import_products:document.getElementById('sheets-import-products').checked,sheets_import_expenses:document.getElementById('sheets-import-expenses').checked};const secret=document.getElementById('google-client-secret').value;if(secret)payload.google_client_secret=secret;await api('/api/settings',{method:'POST',body:JSON.stringify(payload)});await refresh();render();toast(t('settings_saved'))}
function updateChange(){const inp=document.getElementById('cash-received'),el=document.getElementById('change-value');if(!inp||!el)return;el.textContent=money(Math.max(0,Math.round((Number(inp.value)||0)*100)-state.modal.order.total_cents))}
async function settleOrder(id,method){const order=state.modal.order;if(method==='cash'){const received=Number(document.getElementById('cash-received')?.value||order.total_cents/100);if(Math.round(received*100)<order.total_cents)return toast(t('cash_change_error'));await api(`/api/orders/${id}/pay`,{method:'POST',body:JSON.stringify({method,cash_received:received})})}else await api(`/api/orders/${id}/pay`,{method:'POST',body:JSON.stringify({method})});state.modal=null;await refresh();render();toast(t('paid_success'))}
async function showReceipt(id){const order=state.orders.find(o=>o.id===id);if(!order)return;state.modal={type:'receipt',order};render()}
function dateFmt(s){if(!s)return'—';try{return new Intl.DateTimeFormat(state.lang==='ms'?'ms-MY':state.lang==='zh'?'zh-CN':'en-MY',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(s))}catch{return s}}
async function downloadBackup(){try{const res=await fetch('/api/backup',{credentials:'same-origin'});if(!res.ok){const e=await res.json().catch(()=>({}));throw new Error(e.error||t('error'))}const blob=await res.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`kedai-pos-backup-${new Date().toISOString().slice(0,10)}.zip`;a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message)}}
const googleConnected=new URLSearchParams(location.search).get('google')==='connected';if(googleConnected)state.page='settings';boot().then(()=>{if(googleConnected){history.replaceState({},'',location.pathname);toast(t('google_connected'))}});
